mysql --login-path=dba -t -e "SELECT k.table_name AS table_name, k.constraint_name AS foreign_key, k.column_name AS fk_column, s.index_name AS index_it_uses FROM information_schema.key_column_usage AS k JOIN information_schema.statistics AS s ON s.table_schema = k.table_schema AND s.table_name = k.table_name AND s.column_name = k.column_name AND s.seq_in_index = 1 WHERE k.table_schema = 'employees' AND k.referenced_table_name IS NOT NULL AND k.ordinal_position = 1 ORDER BY k.table_name, k.constraint_name"
